def confidence_band(balls_faced: int) -> str:
    if balls_faced <= 5:
        return "1-5"
    if balls_faced <= 15:
        return "6-15"
    if balls_faced <= 30:
        return "16-30"
    if balls_faced <= 45:
        return "31-45"
    return "45+"

def phase_band(over_number: int) -> str:
    if over_number <= 6:
        return "1-6"
    if over_number <= 15:
        return "7-15"
    return "16-20"

def _source_filter(lines: list[str], *, over_number: int, balls_faced: int) -> list[str]:
    phase = phase_band(over_number)
    conf = confidence_band(balls_faced)

    phase_markers = {
        "1-6": (
            "The opening phase is all about setting the tone.",
            "Early in the innings, there is room to build carefully.",
            "This is still the platform-building stage of the innings.",
            "The new-ball phase demands patience and clean judgment.",
            "The field is up, so placement can be priceless.",
        ),
        "7-15": (
            "The middle overs are about rotating strike and finding the gaps.",
            "This is the engine room of the innings.",
            "The field is spreading, so smart placement matters more than raw power.",
            "The middle phase rewards patience and calculated aggression.",
            "Every single matters now as the innings gathers shape.",
        ),
        "16-20": (
            "Now the death overs begin to bite.",
            "Every delivery is becoming a headline moment.",
            "The finishing phase is here and the tempo is rising.",
            "There is no hiding at the death, every ball can change the game.",
            "The last overs are all about nerve, muscle, and execution.",
        ),
    }[phase]

    conf_markers = {
        "1-5": (
            "The batter is still getting a feel for the pace.",
            "Just a handful of balls faced, so timing is still developing.",
            "Fresh at the crease, the batter is reading the bowler carefully.",
            "The first few deliveries are all about finding rhythm.",
            "The early-ball rhythm is not fully settled yet.",
        ),
        "6-15": (
            "The batter is starting to read the bowler now.",
            "Confidence is building after a useful number of deliveries faced.",
            "The timing is beginning to look more natural.",
            "A few balls under the belt and the batter looks increasingly settled.",
            "The stroke selection is getting sharper with each delivery.",
        ),
        "16-30": (
            "Now the batter looks properly set.",
            "That is a batter in rhythm after a long look at the attack.",
            "The longer stay is showing in the quality of shot selection.",
            "Confidence is clearly growing with every ball.",
            "This is the phase where settled batters can control the tempo.",
        ),
        "31-45": (
            "The batter has seen enough to know exactly what is coming.",
            "Thirty-plus balls faced and the reading of length is excellent.",
            "This is seasoned batting now, with experience driving the choices.",
            "The batter looks completely in tune with the conditions.",
            "The longer the stay, the more dangerous this batter becomes.",
        ),
        "45+": (
            "Forty-five-plus balls faced and this batter is fully locked in.",
            "This is a veteran-looking stay at the crease.",
            "The batter is seeing the ball like a beach ball right now.",
            "At this stage of the innings, every shot feels deliberate.",
            "A deeply settled batter is now dictating terms.",
        ),
    }[conf]

    filtered = [line for line in lines if any(m in line for m in phase_markers) and any(m in line for m in conf_markers)]
    if filtered:
        return filtered
    filtered = [line for line in lines if any(m in line for m in phase_markers)]
    if filtered:
        return filtered
    filtered = [line for line in lines if any(m in line for m in conf_markers)]
    return filtered or lines

def get_commentary(
    outcome: str,
    *,
    over_number: int,
    balls_faced: int,
    result: dict[str, Any] | None = None,
) -> str:
    """Return a random commentary that exactly matches the ball outcome."""
    normalized = str(outcome or "").strip().lower()
    if normalized == "wicket":
        normalized = "wicket"
    lines = COMMENTARY_BANK.get(normalized)
    if lines:
        pool = _source_filter(lines, over_number=over_number, balls_faced=balls_faced)
        phase = (
            "powerplay" if int(over_number) <= 6
            else "middle" if int(over_number) <= 15
            else "death"
        )
        if int(balls_faced) <= 5:
            conf = "1-5"
        elif int(balls_faced) <= 15:
            conf = "6-15"
        elif int(balls_faced) <= 30:
            conf = "16-30"
        elif int(balls_faced) <= 45:
            conf = "31-45"
        else:
            conf = "45+"
        key = (normalized, phase, conf)
        last = _LAST_COMMENTARY.get(key)
        choices = [item for item in pool if item != last] or pool
        selected = random.choice(choices)
        _LAST_COMMENTARY[key] = selected
        return selected

    # The uploaded TXT currently contains source lines for dot and single.
    # For every other outcome, use a small exact-result fallback instead of
    # ever showing a commentary line for the wrong result.
    fallback = FALLBACK_COMMENTARY.get(normalized)
    if fallback:
        key = (normalized, "fallback", "fallback")
        last = _LAST_COMMENTARY.get(key)
        choices = [item for item in fallback if item != last] or fallback
        selected = random.choice(choices)
        _LAST_COMMENTARY[key] = selected
        return selected

    payload = dict(result or {})
    payload["outcome"] = "out" if normalized == "wicket" else normalized
    return describe_ball_result(payload)

def available_outcomes() -> tuple[str, ...]:
    return tuple(sorted(COMMENTARY_BANK))
